pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C();
    }

    function testFuzz_property(uint256 initialSum, uint256 laterSum) public {
        vm.assume(initialSum != laterSum);
        address actor = address(0xABCD);

        vm.prank(actor);
        c.SetMinSum(initialSum);

        vm.prank(actor);
        c.Initialized();

        vm.prank(actor);
        c.SetMinSum(laterSum);

        assertTrue(c.MinSum() == initialSum);
    }
}

