pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 val, address actor) public {
        val = bound(val, 1, type(uint128).max);
        vm.assume(actor != address(0));
        vm.prank(actor);
        bool ok;
        try c.SetMinSum(val) { ok = true; } catch { ok = false; }
        // General rule: whenever SetMinSum(val) succeeds, MinSum() must equal val.
        assertTrue(!ok || c.MinSum() == val);
    }
}

