pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address actor, uint256 amount, uint32 lockTime) public {
        vm.assume(actor != address(0));
        amount = bound(amount, 1, 1 ether);
        vm.warp(1000);

        // Initialization path: SetMinSum must succeed and set MinSum to `amount`.
        vm.prank(actor);
        try c.SetMinSum(amount) {
            // ok
        } catch {
            // In the buggy mutant this reverts; the assertion below will catch it
            // because MinSum stays 0 and Collect is no longer gated.
        }

        // Deposit via fallback Put(0) with lockTime 0.
        vm.deal(actor, amount);
        vm.prank(actor);
        (bool okPut, ) = address(c).call{value: amount}(abi.encodeWithSignature("Put(uint256)", uint256(0)));
        assertTrue(okPut && c.Acc(actor).balance == amount);

        // Time passes so unlockTime is reachable.
        vm.warp(2000);

        // Since MinSum == amount and balance == amount, Collect(amount) should be allowed
        // in the correct contract. But in the correct contract SetMinSum actually set
        // MinSum = amount; a Collect attempt of amount+1 must be rejected (balance unchanged).
        // Use Collect(amount + 1): correct contract requires balance >= MinSum(=amount) AND
        // balance >= _am(amount+1) which fails -> balance stays amount.
        vm.prank(actor);
        c.Collect(amount + 1);

        // Reference: SetMinSum succeeded -> MinSum == amount -> Collect(amount+1) rejected -> balance still amount.
        // Mutant: SetMinSum reverted -> MinSum == 0 -> Collect(amount+1) succeeds -> balance becomes 0.
        assertTrue(c.Acc(actor).balance == amount);
    }
}

