pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address actor, uint256 amount) public {
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));
        amount = bound(amount, 1, 1e24);

        vm.deal(actor, amount);

        // Initialize the contract so Put/SetLogFile usage is the normal path.
        vm.prank(actor);
        (bool initOk, ) = address(c).call(abi.encodeWithSignature("Initialized()"));
        assertTrue(initOk, "init should succeed");

        // Register the log file: rule says after SetLogFile succeeds, the stored
        // log target is usable (non-zero), so a later deposit must succeed.
        vm.prank(actor);
        (bool okSet, ) = address(c).call(
            abi.encodeWithSignature("SetLogFile(address)", actor)
        );
        assertTrue(okSet, "SetLogFile should succeed");

        // Deposit via fallback -> Put: succeeds only if LogFile was actually stored.
        vm.prank(actor);
        (bool okPut, ) = address(c).call{value: amount}(abi.encodeWithSignature("Put(uint256)", uint256(0)));

        // Reference: okPut is true for ALL (actor, amount); mutant: LogFile is
        // address(0), so AddMessage reverts and okPut is false.
        assertTrue(okPut, "Put must succeed after a successful SetLogFile");
    }
}

